const RULES_TEXT = "Rules for deciding importance (judge by the BODY; sender, subject and headers are only weak hints):\nNOT important: promotions, discounts, ads, product recommendations, reward or gift blasts, newsletters; order confirmations, receipts and payment confirmations for an order the person just placed; order processing or shipped-with-tracking updates; automated no-reply notices with nothing to act on, auto-replies, out-of-office; job-board alerts and job recommendations; verification codes. Category Newsletter for these (Spam for unsolicited junk or scams).\nIMPORTANT: (a) bank or fintech emails about the person's money: debit alerts, credit alerts, transfers, failed or declined payments, statements, card or account security alerts (a bank's promotional offer is NOT important); (b) delivery news that needs attention: order arrived or delivered, out for delivery today, delivery failed, pickup required, a problem with an order or refund; (c) a real message about a job application, interview, job offer or a recruiter writing to the person (NOT an automated job alert); (d) invoices, tax, legal, government, contracts, medical, deadlines; (e) a real person writing personally with content that matters. Never important for Spam or Newsletter.";
const MAX = 100;
const all = items.map(i => i.json).filter(m => m && (m.id || m.subject || m.Subject));
if (all.length === 0) return [{ json: { empty: true, total: 0, systemPrompt: '', userPrompt: '' } }];

const INVIS = /[\u00AD\u034F\u061C\u115F\u1160\u17B4\u17B5\u180E\u2000-\u200F\u2028-\u202F\u205F-\u206F\u3000\uFEFF]/g;
function stripHtml(h) {
  return String(h).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#?\w+;/g, ' ');
}
function tidy(t) {
  return String(t || '').replace(/https?:\/\/\S+/g, ' ').replace(INVIS, ' ').replace(/[-=_*]{4,}/g, ' ').replace(/\s+/g, ' ').trim();
}
function bodyOf(m) {
  const a = tidy(m.text);
  if (a.length >= 30) return a.slice(0, 1200);
  const b = tidy(stripHtml(m.html || ''));
  if (b.length >= 30) return b.slice(0, 1200);
  return tidy(m.snippet).slice(0, 1200) || '(empty body)';
}
function senderOf(m) {
  const f = m.from || m.From;
  if (f && typeof f === 'object') {
    return f.text || (f.value && f.value[0] && ((f.value[0].name ? f.value[0].name + ' ' : '') + '<' + f.value[0].address + '>')) || 'unknown';
  }
  return f || 'unknown';
}
const rows = all.slice(0, MAX).map((m, idx) => ({
  i: idx,
  from: String(senderOf(m)).slice(0, 90),
  subject: String(m.subject || m.Subject || '(no subject)').slice(0, 120),
  in_spam_folder: Array.isArray(m.labelIds) && m.labelIds.includes('SPAM'),
  unsubscribe_header: !!(m.headers && m.headers['list-unsubscribe']),
  body: bodyOf(m)
}));
const meta = rows.map(r => ({ i: r.i, from: r.from, subject: r.subject, in_spam_folder: r.in_spam_folder }));

const system = `You are an email sorting, notification and analysis assistant for one person's inbox. You never write replies. You are given every email received today, from BOTH the Inbox and the Spam folder. Read each email's body together with its sender and subject, and return ONLY valid JSON, no markdown.

__RULES__

in_spam_folder only says where Gmail put the email. Gmail sometimes puts genuinely important mail in Spam, so judge the content, not the folder.

For EVERY email index return: category (Sales|Support|Billing|Technical|Internal|Partnership|Spam|Newsletter|Other), priority (Low|Medium|High|Urgent), is_important (boolean), confidence (integer 0-100), summary (max 20 words saying what the email actually is, e.g. "Temu promotion: free gifts offer"), action_needed (short sentence, or "None").
Also return analysis: 3-5 sentences on the day's inbox: themes, risks, what the person should look at first.
Return exactly: {"results":[{"i":0,"category":"","priority":"","is_important":false,"confidence":0,"summary":"","action_needed":""}],"analysis":""}`.replace('__RULES__', RULES_TEXT);

const userPrompt = 'Emails received today:\n' + JSON.stringify(rows);
return [{ json: { empty: false, total: all.length, analyzed: rows.length, truncated: all.length >= MAX, meta, systemPrompt: system, userPrompt } }];

const prep = $('Build Digest Prompt').item.json;
const meta = prep.meta;
let parsed, err = null;
try {
  const r = items[0].json;
  if (r.error) throw new Error(String(typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))).replace(/\s+/g, ' ').slice(0, 160));
  const txt = r.output;
  const m = txt.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(m ? m[0] : txt);
} catch (e) { err = e.message; parsed = { results: [], analysis: '' }; }

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '...' : s; };
const results = Array.isArray(parsed.results) ? parsed.results : [];
if (err || results.length === 0) {
  return [{ json: { text: `:warning: *AI model issue - the 3-hour inbox digest could not be generated*\nThe Gemini model failed after retries while analysing today's ${prep.total} emails. Nothing was lost: the next digest will analyse the whole day again.\n*Error:* ${esc(err || 'empty response from the model')}\n*Please check:* the Gemini credential, model name and API quota/billing in n8n.` } }];
}
const byI = {}; for (const r of results) byI[r.i] = r;

const rows = meta.map(m => ({ m, r: byI[m.i] || null }));
const classified = rows.filter(x => x.r);
const important = classified.filter(x => x.r.is_important === true && x.r.category !== 'Spam' && x.r.category !== 'Newsletter');
const impSet = new Set(important.map(x => x.m.i));
const junk = classified.filter(x => x.r.category === 'Spam');
const promo = classified.filter(x => x.r.category === 'Newsletter');
const other = classified.filter(x => !impSet.has(x.m.i) && x.r.category !== 'Spam' && x.r.category !== 'Newsletter');
const unclassified = rows.length - classified.length;

const order = { Urgent: 0, High: 1, Medium: 2, Low: 3 };
important.sort((a, b) => (order[a.r.priority] ?? 9) - (order[b.r.priority] ?? 9));
const pri = { Urgent: 0, High: 0, Medium: 0, Low: 0 };
for (const x of important) if (pri[x.r.priority] !== undefined) pri[x.r.priority]++;
let confSum = 0, confN = 0;
for (const x of classified) { const c = parseInt(x.r.confidence, 10); if (!isNaN(c)) { confSum += c; confN++; } }
const avgConf = confN ? Math.round(confSum / confN) : 0;
const spamFolder = meta.filter(m => m.in_spam_folder).length;
const impInSpam = important.filter(x => x.m.in_spam_folder);

const time = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Africa/Lagos' });
let t = `:bar_chart: *Inbox digest - today so far, as of ${time} (WAT)*\n`;
t += `*Total emails:* ${prep.total} (Inbox ${prep.total - spamFolder}, Spam folder ${spamFolder})${prep.truncated ? ' - newest ' + prep.analyzed + ' analysed' : ''}\n`;
t += `*Important:* ${important.length}  |  *Promotions / newsletters:* ${promo.length}  |  *Spam / junk:* ${junk.length}  |  *Other:* ${other.length}\n`;
t += `*Urgency of important emails:* Urgent ${pri.Urgent}, High ${pri.High}, Medium ${pri.Medium}, Low ${pri.Low}\n`;
t += `*Confidence:* ${avgConf}% average` + (unclassified ? ` (${unclassified} emails could not be classified)` : '') + `\n`;
if (impInSpam.length) t += `:warning: *${impInSpam.length} important email(s) are sitting in your SPAM folder - check them!*\n`;
if (err) t += `:warning: AI analysis failed: ${esc(err)}\n`;
if (parsed.analysis) t += `\n*Analysis:* ${esc(parsed.analysis)}\n`;

function section(title, list, max, withAction) {
  if (!list.length) return '';
  let s = `\n*${title} (${list.length})*\n`;
  for (const x of list.slice(0, max)) {
    const loc = x.m.in_spam_folder ? ' :warning: _in Spam folder_' : '';
    const pr = withAction ? `[${x.r.priority}] ` : '';
    const act = withAction && x.r.action_needed && !/^none/i.test(x.r.action_needed) ? ` -> ${esc(cut(x.r.action_needed, 100))}` : '';
    s += `- ${pr}${esc(cut(x.m.from, 50))} - ${esc(cut(x.m.subject, 70))}: ${esc(cut(x.r.summary, 140))}${act}${loc}\n`;
  }
  if (list.length > max) s += `...and ${list.length - max} more\n`;
  return s;
}
t += section('IMPORTANT - needs you', important, 20, true);
t += section('Promotions and newsletters', promo, 15, false);
t += section('Spam / junk', junk, 15, false);
t += section('Other', other, 15, false);
return [{ json: { text: t.slice(0, 38000) } }];

