// One throttled "AI model issue" notice instead of one Slack message per email.
const sd = $getWorkflowStaticData('global');
const COOLDOWN_MS = 60 * 60 * 1000;   // at most one AI-issue alert per hour
const now = Date.now();
const esc = s => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

sd.aiFailCount = (sd.aiFailCount || 0) + items.length;
sd.aiLastError = items[items.length - 1].json.aiError || 'unknown error';
sd.aiRecent = [...(sd.aiRecent || []), ...items.map(i => `${i.json.sender} - ${i.json.subject}`)].slice(-5);

if (sd.aiLastAlert && now - sd.aiLastAlert < COOLDOWN_MS) return [];   // already reported recently

let t = `:warning: *AI model issue - emails could not be classified*\n`;
t += `The Gemini model failed (after retries) on *${sd.aiFailCount}* new email(s). Nothing was labelled or sent to Slack for them; they were left untouched and the next 3-hour digest will still pick them up.\n`;
t += `*Latest error:* ${esc(sd.aiLastError)}\n`;
t += `*Latest affected emails:*\n` + sd.aiRecent.map(x => `- ${esc(x).slice(0, 140)}`).join('\n') + `\n`;
t += `*Please check:* the Gemini credential, model name and API quota/billing in n8n.\n`;
t += `_Further AI-issue alerts are limited to one per hour._`;

sd.aiLastAlert = now; sd.aiFailCount = 0; sd.aiRecent = [];
return [{ json: { text: t } }];

const results = [];
for (const item of items) {
  const msg = item.json;
  const subject = msg.subject || msg.Subject || '';
  const from = msg.from || msg.From || '';
  const body = msg.text || msg.html || msg.snippet || '';

  const errors = [];
  if (!from) errors.push('missing_sender');
  if (!subject) errors.push('missing_subject');
  if (!body || body.trim().length === 0) errors.push('empty_body');
  if (body && body.length > 200000) errors.push('body_too_large');

  results.push({
    json: {
      ...msg,
      isValid: errors.length === 0,
      validationErrors: errors
    }
  });
}
return results;

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function removeSignatureAndDisclaimers(text) {
  if (!text) return '';
  const cutPatterns = [
    /--\s*\n[\s\S]*$/,
    /\nSent from my iPhone[\s\S]*$/i,
    /\nSent from my Android[\s\S]*$/i,
    /\nGet Outlook for[\s\S]*$/i,
    /\nBest regards,[\s\S]*$/i,
    /\nKind regards,[\s\S]*$/i,
    /\nThis email and any attachments[\s\S]*$/i,
    /\nThis message contains confidential information[\s\S]*$/i,
    /\nDISCLAIMER:[\s\S]*$/i,
    /\nCONFIDENTIALITY NOTICE[\s\S]*$/i
  ];
  let cleaned = text;
  for (const pattern of cutPatterns) {
    cleaned = cleaned.replace(pattern, '');
  }
  return cleaned.trim();
}

const results = [];
for (const item of items) {
  const msg = item.json;
  const rawBody = msg.text || msg.html || msg.snippet || '';
  const isHtml = !!msg.html && !msg.text;
  const stripped = isHtml ? stripHtml(rawBody) : rawBody;
  const cleanedBody = removeSignatureAndDisclaimers(stripped).slice(0, 12000);

  const attachments = msg.attachments || (msg.payload && msg.payload.parts)
    ? (Array.isArray(msg.attachments) ? msg.attachments.length : 0)
    : 0;

  results.push({
    json: {
      messageId: msg.id || msg.messageId || '',
      threadId: msg.threadId || '',
      sender: (msg.from && typeof msg.from === 'object' ? (msg.from.text || (msg.from.value && msg.from.value[0] && ((msg.from.value[0].name ? msg.from.value[0].name + ' ' : '') + '<' + msg.from.value[0].address + '>'))) : (msg.from || msg.From)) || 'unknown@unknown.com',
      subject: msg.subject || msg.Subject || '(no subject)',
      cleanedBody: cleanedBody || '(empty body)',
      hasAttachments: attachments > 0,
      inSpam: Array.isArray(msg.labelIds) && msg.labelIds.includes('SPAM'),
      hasUnsubscribeHeader: !!(msg.headers && (msg.headers['list-unsubscribe'] || msg.headers['list-id'])),
      isAutoSubmitted: !!(msg.headers && msg.headers['auto-submitted'] && !/no/i.test(msg.headers['auto-submitted'])),
      attachmentCount: attachments
    }
  });
}
return results;

// Replace these placeholder values with the real Gmail Label IDs
// (Resource: Label, Operation: Get Many on a temporary Gmail node will list them)
const labelMap = {
  "Sales": "YOUR_LABEL_ID_SALES",
  "Support": "YOUR_LABEL_ID_SUPPORT",
  "Billing": "YOUR_LABEL_ID_BILLING",
  "Technical": "YOUR_LABEL_ID_TECHNICAL",
  "Internal": "YOUR_LABEL_ID_INTERNAL",
  "Partnership": "YOUR_LABEL_ID_PARTNERSHIP",
  "Spam": "SPAM",
  "Newsletter": "YOUR_LABEL_ID_NEWSLETTER",
  "Other": "YOUR_LABEL_ID_OTHER"
};

return items.map(item => ({
  json: {
    ...item.json,
    gmailLabelId: labelMap[item.json.category] || labelMap["Other"]
  }
}));

const NEEDS_REVIEW_LABEL_ID = "YOUR_LABEL_ID_NEEDS_REVIEW";
const labelMap = {
  "Sales": "YOUR_LABEL_ID_SALES",
  "Support": "YOUR_LABEL_ID_SUPPORT",
  "Billing": "YOUR_LABEL_ID_BILLING",
  "Technical": "YOUR_LABEL_ID_TECHNICAL",
  "Internal": "YOUR_LABEL_ID_INTERNAL",
  "Partnership": "YOUR_LABEL_ID_PARTNERSHIP",
  "Spam": "SPAM",
  "Newsletter": "YOUR_LABEL_ID_NEWSLETTER",
  "Other": "YOUR_LABEL_ID_OTHER"
};
return items.map(item => {
  const catLabel = labelMap[item.json.category] || labelMap["Other"];
  return { json: { ...item.json, gmailLabelIds: [NEEDS_REVIEW_LABEL_ID, catLabel] } };
});

