const results = [];
const VALID_CATEGORIES = ['Sales','Support','Billing','Technical','Internal','Partnership','Spam','Newsletter','Other'];
const VALID_PRIORITIES = ['Low','Medium','High','Urgent'];
const CONFIDENCE_THRESHOLD = 80;

for (let i = 0; i < items.length; i++) {
  const original = items[i].json;
  const cleaned = $('Clean HTML & Extract Metadata').item.json;
  let parsed = null;
  let parseError = null;

  try {
    if (original.error) {
      const em = typeof original.error === 'string' ? original.error : (original.error.message || JSON.stringify(original.error));
      throw new Error('AI model error: ' + String(em).replace(/\s+/g, ' ').slice(0, 160));
    }

    const content = original.output
      ? (typeof original.output === 'string' ? original.output : JSON.stringify(original.output))
      : null;

    if (!content) {
      throw new Error('No content returned from Gemini API');
    }

    const jsonMatch = content.match(/\{[\s\S]*\}/);
    const jsonText = jsonMatch ? jsonMatch[0] : content;
    parsed = JSON.parse(jsonText);

    if (!VALID_CATEGORIES.includes(parsed.category)) {
      parsed.category = 'Other';
    }
    if (!VALID_PRIORITIES.includes(parsed.priority)) {
      parsed.priority = 'Low';
    }
    parsed.confidence = Math.max(0, Math.min(100, parseInt(parsed.confidence, 10) || 0));
    parsed.summary = parsed.summary || '';
    parsed.action_needed = parsed.action_needed || '';
    parsed.reasoning = parsed.reasoning || '';

    parsed.is_important = !!parsed.is_important;
    const isBulk = parsed.category === 'Spam' || parsed.category === 'Newsletter';
    if (isBulk) {
      // Spam / newsletters / generic promos: label only. Never review, never reply.
      parsed.is_important = false;
      parsed.needs_review = false;
    } else {
      // Only important (bank/serious/direct) or low-confidence non-bulk mail goes to review.
      parsed.needs_review = parsed.is_important || parsed.confidence < CONFIDENCE_THRESHOLD;
    }
  } catch (err) {
    parseError = err.message;
    // AI failed: no labels, no Slack alert for this email. It is reported once (throttled) as an AI model issue.
    parsed = {
      summary: '', category: 'Other', priority: 'Low', confidence: 0,
      needs_review: false, is_important: false, action_needed: '', reasoning: '',
      aiFailed: true,
      aiError: String(parseError || 'unknown error').replace(/\s+/g, ' ').slice(0, 200)
    };
  }

  results.push({
    json: {
      messageId: cleaned.messageId,
      threadId: cleaned.threadId,
      sender: cleaned.sender,
      subject: cleaned.subject,
      inSpam: !!cleaned.inSpam,
      cleanedBody: cleaned.cleanedBody,
      aiFailed: false,
      ...parsed,
      processingError: parseError
    }
  });
}
return results;

